<template><ContentWrap><el-button type="primary" @click="createNew">新增数字人</el-button><el-table :data="rows"><el-table-column prop="name" label="名称"/><el-table-column prop="code" label="Code"/><el-table-column prop="avatarType" label="形象"/><el-table-column prop="agentId" label="Agent"/><el-table-column prop="voiceId" label="音色"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link @click="preview(row)">预览</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-dialog v-model="open" title="数字人"><el-form :model="form" label-width="110px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="Code"><el-input v-model="form.code"/></el-form-item><el-form-item label="Agent ID"><el-input-number v-model="form.agentId"/></el-form-item><el-form-item label="形象类型"><el-select v-model="form.avatarType"><el-option v-for="x in avatars" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="形象 URL"><el-input v-model="form.avatarUrl"/></el-form-item><el-form-item label="TTS Model"><el-input-number v-model="form.voiceModelId"/></el-form-item><el-form-item label="音色"><el-input v-model="form.voiceId"/></el-form-item><el-form-item label="口型"><el-select v-model="form.lipSyncMode"><el-option label="音量驱动" value="AUDIO_LEVEL"/><el-option label="Viseme" value="VISEME"/><el-option label="Provider" value="PROVIDER"/></el-select></el-form-item><el-form-item label="欢迎语"><el-input v-model="form.welcomeText"/></el-form-item><el-form-item label="允许打断"><el-switch v-model="form.interruptEnabled"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<DigitalHumanPreview v-model="previewOpen" :config="previewConfig"/></ContentWrap></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{DigitalHumanApi,type DigitalHumanPreviewVO,type DigitalHumanVO,type AvatarType}from'@/api/ai/digital-human';import DigitalHumanPreview from'./components/DigitalHumanPreview.vue';const rows=ref<DigitalHumanVO[]>([]),open=ref(false),editing=ref<number>(),previewOpen=ref(false),previewConfig=ref<DigitalHumanPreviewVO>();const avatars:AvatarType[]=['STATIC_2D','LIVE2D','THREE_D','EXTERNAL'];const form=reactive<any>({name:'',code:'',agentId:0,avatarType:'STATIC_2D',lipSyncMode:'AUDIO_LEVEL',interruptEnabled:true,status:'ENABLED'});async function load(){rows.value=await DigitalHumanApi.list()}function createNew(){editing.value=undefined;Object.assign(form,{name:'',code:'',agentId:0,avatarType:'STATIC_2D',avatarUrl:'',voiceModelId:undefined,voiceId:'',lipSyncMode:'AUDIO_LEVEL',welcomeText:'',interruptEnabled:true,status:'ENABLED'});open.value=true}function edit(r:DigitalHumanVO){editing.value=r.id;Object.assign(form,r);open.value=true}async function save(){editing.value?await DigitalHumanApi.update(editing.value,form):await DigitalHumanApi.create(form);open.value=false;await load()}async function remove(r:DigitalHumanVO){await DigitalHumanApi.delete(r.id);await load()}async function preview(r:DigitalHumanVO){previewConfig.value=await DigitalHumanApi.preview(r.id);previewOpen.value=true}onMounted(load)</script>